from pathlib import Path
import subprocess
r=Path.home()/'bplus-drop';t=Path('/tmp/gesture117');t.mkdir(exist_ok=True)
(t/'Tests.java').write_text('''import com.bplus.share.SelectionGesture;public class Tests{static int n;static void ok(boolean b,String s){if(!b)throw new RuntimeException(s);n++;System.out.println("PASS "+s);}public static void main(String[] a){SelectionGesture g=new SelectionGesture();
ok(!g.event(0,false,10,10,8),"inactive DOWN stays with card");ok(!g.event(1,true,10,10,8)&&!g.toggle,"long-click entered selection: same UP must not deselect");ok(g.event(0,true,10,10,8),"next selected-mode DOWN owned by selection");ok(g.event(1,true,10,10,8)&&g.toggle,"next tap deselects exactly once");
for(int i=0;i<5;i++){ok(!g.event(0,false,10,10,8),"re-entry DOWN stays with card cycle "+i);ok(!g.event(1,true,10,10,8)&&!g.toggle,"re-entry long-press UP preserves selection cycle "+i);g.event(0,true,10,10,8);ok(g.event(1,true,10,10,8)&&g.toggle,"deselect tap cycle "+i);}
g.event(0,true,10,10,8);g.event(2,true,40,10,8);ok(g.event(1,true,40,10,8)&&!g.toggle,"drag is not a selection tap");g.event(0,true,10,10,8);g.event(3,true,10,10,8);ok(!g.toggle,"cancel does not toggle");g.event(0,false,10,10,8);ok(!g.event(1,false,10,10,8)&&!g.toggle,"normal inactive short tap remains open gesture");System.out.println(n+" gesture ownership assertions; Android event dispatch/runtime still requires phone verification.");}}''')
j=Path.home()/'jdk17/bin';subprocess.run([str(j/'javac'),'-d',str(t),str(r/'app/src/com/bplus/share/SelectionGesture.java'),str(t/'Tests.java')],check=True)
